package com.google.javascript.rhino.jstype;

import com.google.common.base.Predicate;
import com.google.javascript.rhino.ErrorReporter;
import com.google.javascript.rhino.JSDocInfo;
import com.google.javascript.rhino.jstype.JSTypeRegistry.ResolveMode;
import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.Comparator;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Unit tests for JSType.isEmptyType().
 */
public class JSType_isEmptyType_TriageGen1Test {

    @Test
    public void testIsEmptyType_isNoTypeTrue() {
        JSType jsType = mock(JSType.class);
        when(jsType.isNoType()).thenReturn(true);
        // Short-circuit: isNoObjectType and isNoResolvedType shouldn't matter
        assertTrue("isEmptyType should be true if isNoType is true", jsType.isEmptyType());
    }

    @Test
    public void testIsEmptyType_isNoObjectTypeTrue() {
        JSType jsType = mock(JSType.class);
        when(jsType.isNoType()).thenReturn(false);
        when(jsType.isNoObjectType()).thenReturn(true);
        // Short-circuit: isNoResolvedType shouldn't matter
        assertTrue("isEmptyType should be true if isNoObjectType is true", jsType.isEmptyType());
    }

    @Test
    public void testIsEmptyType_isNoResolvedTypeTrue() {
        JSType jsType = mock(JSType.class);
        when(jsType.isNoType()).thenReturn(false);
        when(jsType.isNoObjectType()).thenReturn(false);
        when(jsType.isNoResolvedType()).thenReturn(true);
        assertTrue("isEmptyType should be true if isNoResolvedType is true", jsType.isEmptyType());
    }

    @Test
    public void testIsEmptyType_allFalse() {
        JSType jsType = mock(JSType.class);
        when(jsType.isNoType()).thenReturn(false);
        when(jsType.isNoObjectType()).thenReturn(false);
        when(jsType.isNoResolvedType()).thenReturn(false);
        assertFalse("isEmptyType should be false if all component methods return false", jsType.isEmptyType());
    }
}
